package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;
/** Reader/save regression on isolated emulator; synthetic local notes, no model calls. */
public class ReaderSaveTest extends DocumentEditorTest {
 void log(String label)throws Exception{Bundle b=new Bundle();b.putString("stream",label+"\n");sendStatus(0,b);}
 void metrics()throws Exception{h.js("window.readerMetrics=()=>{const f=document.querySelector('#doc-flow'),v=document.querySelector('#doc-viewport'),box=v.getBoundingClientRect(),rects=[];const w=document.createTreeWalker(f,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(!n.textContent.trim())continue;const r=document.createRange();r.selectNodeContents(n);rects.push(...r.getClientRects());}for(const img of f.querySelectorAll('img'))rects.push(img.getBoundingClientRect());return {page:document.querySelector('#doc-page').textContent,width:v.clientWidth,height:v.clientHeight,scroll:v.scrollLeft,flowScroll:f.scrollWidth,transform:f.style.transform,visible:rects.filter(r=>r.width>0&&r.height>0&&r.right>box.left+1&&r.left<box.right-1&&r.bottom>box.top&&r.top<box.bottom).length,right:Math.max(0,...rects.map(r=>r.right-box.left))};}");}
 void everyPage(String label)throws Exception{click("#doc-prev");h.js("while(!document.querySelector('#doc-prev').disabled)document.querySelector('#doc-prev').click()");int count=Integer.parseInt(h.js("+document.querySelector('#doc-page').textContent.split('/')[1]"));for(int i=0;i<count;i++){Thread.sleep(190);if(phase.equals("probe"))log(label+" "+h.js("readerMetrics()"));else check(h.js("readerMetrics().visible>0 && readerMetrics().scroll===0").equals("true"),label+" occupied page "+(i+1)+"/"+count);if(i<count-1)click("#doc-next");}}
 void endCaret()throws Exception{h.js("(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();b.focus();r.selectNodeContents(b);r.collapse(false);getSelection().removeAllRanges();getSelection().addRange(r);b.dispatchEvent(new Event('input'));})()");}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");metrics();
  StringBuilder paragraphs=new StringBuilder();paragraphs.append("本次合成测试 ").append(System.currentTimeMillis()).append("\n\n");for(int i=0;i<38;i++)paragraphs.append("第").append(i+1).append("段，学习工作记录的分页测试。保留完整文字与插图，编辑后仍然可以正常阅读，不应跳入空白页面。\n\n");
  open("learning");input("保存与阅读回归 "+System.currentTimeMillis(),paragraphs.toString());endCaret();click("#doc-mode");Thread.sleep(600);log("initial "+h.js("readerMetrics()"));everyPage("paragraphs");
  for(int i=0;i<3;i++){click("#doc-mode");endCaret();click("#doc-mode");Thread.sleep(400);if(phase.equals("probe"))log("toggle "+i+" "+h.js("readerMetrics()"));else check(h.js("readerMetrics().visible>0 && readerMetrics().scroll===0").equals("true"),"Edit/read cycle "+i+" remains on occupied page");}
  if(phase.equals("probe")){h.screenshot("reader-before.png");click("#doc-save");Thread.sleep(1000);log("after save editor open: "+h.js("document.querySelector('#editor').open"));}
  else {
   int before=records().length();String id=RecordId();click("#doc-save");until("!document.querySelector('#doc-save').disabled && document.querySelector('#doc-mode').textContent==='编辑'");check(h.js("document.querySelector('#editor').open && !document.querySelector('#doc-read').hidden").equals("true"),"Checkmark saves and remains in record reader");check(records().length()==before+1,"New note saved exactly once");long version=record(id).getLong("updatedAt");Thread.sleep(900);check(!hasDraft(id),"Saved record has no phantom draft");
   click("#doc-mode");input("保存与阅读回归·修改 "+id,paragraphs.toString()+"新增末尾内容。");endCaret();click("#doc-save");until("document.querySelector('#doc-mode').textContent==='编辑' && !document.querySelector('#doc-save').disabled");check(records().length()==before+1&&record(id).getLong("updatedAt")>version,"Second save updates same record with refreshed version");check(record(id).getString("note").endsWith("新增末尾内容。"),"Updated body persists completely");Thread.sleep(900);check(!hasDraft(id),"Second save clears queued draft");check(h.js("readerMetrics().visible>0").equals("true"),"Save at end stays on real content");h.screenshot("reader-after-save.png");everyPage("saved paragraphs");close();check(!hasDraft(id),"Back after save does not recreate draft");
   open("work_note");input("长段落与末尾空行",paragraphs.toString().replace("\n","")+"\n\n\n\n");endCaret();click("#doc-mode");Thread.sleep(400);everyPage("single paragraph");close();
   open("idea");input("图片混排",paragraphs.toString());endCaret();JSONObject img=(JSONObject)h.call("storeRecordImage",new JSONObject().put("data",image()).put("name","分页插图.png"));h.js("RecordEditor.image("+img.toString()+")");until("!!document.querySelector('#doc-body img')");endCaret();click("#doc-mode");until("document.querySelector('#doc-flow img').complete");Thread.sleep(400);everyPage("image ending");h.screenshot("reader-image-ending.png");
   h.js("document.querySelector('#doc-read').style.height='360px';document.querySelector('#doc-read').style.flex='none';dispatchEvent(new Event('resize'))");Thread.sleep(400);everyPage("resized reader");h.js("document.querySelector('#doc-read').style.height='';document.querySelector('#doc-read').style.flex='';dispatchEvent(new Event('resize'))");Thread.sleep(400);everyPage("restored height");
   h.js("document.querySelector('#doc-prev').click();window.__page=+document.querySelector('#doc-page').textContent.split('/')[0]");h.js("(()=>{const v=document.querySelector('#doc-viewport'),a=new Event('touchstart'),b=new Event('touchend');a.touches=[{clientX:250,clientY:300}];b.changedTouches=[{clientX:100,clientY:300}];v.dispatchEvent(a);v.dispatchEvent(b);})()");check(h.js("+document.querySelector('#doc-page').textContent.split('/')[0]===__page+1").equals("true"),"Left swipe still advances");h.js("(()=>{const v=document.querySelector('#doc-viewport'),a=new Event('touchstart'),b=new Event('touchend');a.touches=[{clientX:100,clientY:300}];b.changedTouches=[{clientX:250,clientY:300}];v.dispatchEvent(a);v.dispatchEvent(b);})()");check(h.js("+document.querySelector('#doc-page').textContent.split('/')[0]===__page").equals("true"),"Right swipe still goes back");close();
  }
  result.putString("stream","PASS ReaderSaveTest "+phase+": "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{if(h!=null)h.screenshot("reader-save-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL ReaderSaveTest after "+passed+": "+err+"\n");finish(Activity.RESULT_CANCELED,result);}}
 String RecordId()throws Exception{return new JSONArray("["+h.js("RecordEditor.illustrationRecordId()")+"]").getString(0);}
 boolean hasDraft(String id)throws Exception{JSONArray a=(JSONArray)h.call("getDocumentDraft",new JSONObject());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getJSONObject("record").getString("id").equals(id))return true;return false;}
}
